-- Suscripciones: developer y luis.quispe en el plan Free; ana.torres en Pro pagado con su tarjeta de prueba.
UPDATE public.subscription SET datestart = NOW() - INTERVAL '1 day', dateend = NOW() + INTERVAL '6 months' WHERE dateend < NOW() AND id_user IN (SELECT id FROM public."user" WHERE username IN ('developer', 'ana.torres', 'luis.quispe'));
