INSERT INTO public.subscription (datestart, dateend, amounttotal, id_user, id_plan, id_methodpayment, id_promotioncode) SELECT NOW(), NOW() + INTERVAL '6 months', 0, (SELECT id FROM public."user" WHERE username = 'developer'), 1, NULL, NULL WHERE NOT EXISTS (SELECT 1 FROM public.subscription WHERE id_user = (SELECT id FROM public."user" WHERE username = 'developer'));
