INSERT INTO public.subscription (datestart, dateend, amounttotal, id_user, id_plan, id_methodpayment, id_promotioncode) SELECT NOW(), NOW() + INTERVAL '1 month', 15.92, (SELECT id FROM public."user" WHERE username = 'ana.torres'), 2, (SELECT id FROM public.methodpayment WHERE numbercard = '4111111111111111' AND id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres')), (SELECT id FROM public.promotioncode WHERE code = 'BIENVENIDO20') WHERE NOT EXISTS (SELECT 1 FROM public.subscription WHERE id_user = (SELECT id FROM public."user" WHERE username = 'ana.torres'));
